        foreach(var id in new[]{"drayven","titanica","jabalinero","maestro-de-las-mareas"})
        {
            var character=AssetDatabase.LoadAssetAtPath<CharacterDefinition>("Assets/resources/MonsterPouch/Characters/"+id+"/Character.asset");
            if(character==null){lines.Add(id+": missing Character");continue;}
            lines.Add(id+"/General: "+JsonUtility.ToJson(character.General));
            foreach(var asset in new[]{character.Ability}.Concat(character.Upgrades??Array.Empty<CharacterAbility>()))
            {
                if(asset==null){lines.Add(id+": missing ability");continue;}
                lines.Add(AssetDatabase.GetAssetPath(asset)+"/raw: "+JsonUtility.ToJson(asset.Definition));
                lines.Add(AssetDatabase.GetAssetPath(asset)+"/copy: "+JsonUtility.ToJson(asset.Copy()));
            }
        }
        return string.Join("\n",lines);
    }
    public static string ValidateBatch(string faction, bool requireRegistered = false)
    {
        string[] names = { "geothar", "aireola", "aquarion", "naturalis", "volkanar" };
        int group = Array.IndexOf(names, faction);
        if (group < 0) throw new ArgumentException("Unknown faction", nameof(faction));
        return Validate(requireRegistered, CharacterIds.Skip(group * 4).Take(4).ToArray(), faction);
    }
    static string Validate(bool requireRegistered, string[] selectedIds = null, string faction = null)
    {
        var errors = new List<string>();
        var ids = selectedIds ?? CharacterIds;
        int checkedSprites = 0;
        foreach (var item in Sprites)
        {
            var fields = item.Split('|'); var path = fields[0];
            if (faction != null && path.IndexOf(faction, StringComparison.OrdinalIgnoreCase) < 0 &&
                !ids.Any(id => path.IndexOf("/" + id + "/", StringComparison.OrdinalIgnoreCase) >= 0)) continue;
            checkedSprites++;
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null || importer.textureType != TextureImporterType.Sprite || importer.spriteImportMode != SpriteImportMode.Single)
                errors.Add("Sprite importer required: " + path);
            if (AssetDatabase.AssetPathToGUID(path) != fields[1]) errors.Add("GUID differs: " + path);
            var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(path);
            if (sprite == null || sprite.texture == null || sprite.rect.width <= 0 || sprite.rect.height <= 0)
                errors.Add("Sprite load failed: " + path);
            else if (Mathf.Abs(sprite.pixelsPerUnit - float.Parse(fields[2], System.Globalization.CultureInfo.InvariantCulture)) > .001f)
                errors.Add("Sprite PPU differs: " + path);
            const string prefix = "Assets/resources/";
            if (path.StartsWith(prefix, StringComparison.Ordinal))
            {
                string resource = path.Substring(prefix.Length, path.Length-prefix.Length-4);
                if (Resources.Load<Sprite>(resource) == null) errors.Add("Resources Sprite load failed: " + resource);
            }
        }
        var config = Resources.Load<MatchConfig>("MonsterPouch/MatchConfig");
        foreach (var id in ids)
        {
            var character = AssetDatabase.LoadAssetAtPath<CharacterDefinition>("Assets/resources/MonsterPouch/Characters/"+id+"/Character.asset");
            if (character == null || character.Id != id) { errors.Add("Character load failed: " + id); continue; }
            if(CharacterUiArtwork.Icon(id)==null||CharacterUiArtwork.Card(id)==null||CharacterUiArtwork.Portrait(id)==null)
                errors.Add("Character UI lookup failed: "+id);
            if(AbilityUiCatalog.Get(id+"/basic")==null)errors.Add("Basic icon lookup failed: "+id);
            if(LeaderBadgeArtwork.FactionFor(id)=="monsters"||LeaderBadgeArtwork.Get(id,false)==null||LeaderBadgeArtwork.Get(id,true)==null)
                errors.Add("Leader badge lookup failed: "+id);
            var definition=character.CreateRuntimeDefinition();
            foreach(var ability in new[]{definition.BaseAbility,definition.PassiveAbility}.Concat(definition.Tricks).Where(a=>a!=null))
            {
                string key=ability.EffectId??ability.Id;
                if(AbilityUiCatalog.Get(key)==null||!AbilityUiCatalog.HasDescription(key))errors.Add("Ability UI lookup failed: "+key);
                foreach(bool spanish in new[]{false,true})
                {
                    string copy=GameText.AbilityDescription(ability,definition,spanish);
                    if(string.IsNullOrWhiteSpace(copy)||copy.Contains("{")||copy.Contains("}"))errors.Add("Unresolved ability copy: "+key);
                }
            }
            string validation = character.Validate();
            if (!string.IsNullOrEmpty(validation)) errors.Add(id + ": " + validation);
            if (character.Portrait == null || character.Card == null || character.Icon == null || character.Visuals == null)
                errors.Add("Missing imported UI/body reference: " + id);
            if (requireRegistered && (config == null || config.Characters == null || !config.Characters.Contains(character)))
                errors.Add("Character not registered: " + id);
        }
        if(requireRegistered && selectedIds == null && (config?.Characters==null||config.Characters.Length!=44||config.Characters.Select(c=>c.Id).Distinct().Count()!=44))
            errors.Add("The configured roster must contain exactly 44 unique characters.");
        foreach(var folder in new[]{"BattleHomeIdles","LobbyFrames","LobbyGestures"})
        {
            var catalog=Resources.Load<TextAsset>("MonsterPouch/UI/"+folder+"/clips");
            var clips=catalog!=null?JsonUtility.FromJson<LobbyManifest>(catalog.text)?.clips:null;
            foreach(var id in ids)
            {
                var clip=clips?.SingleOrDefault(c=>c.id==id);
                if(clip==null){errors.Add("Lobby entry missing: "+folder+"/"+id);continue;}
                foreach(var resource in new[]{clip.texture,clip.idleTexture})
                    if(!string.IsNullOrEmpty(resource)&&Resources.Load<Texture2D>(resource)==null)
                        errors.Add("Lobby texture load failed: "+resource);
            }
        }
        if (errors.Count > 0) throw new InvalidOperationException("Import acceptance failed ("+errors.Count+"): \n"+string.Join("\n",errors.Take(30)));
        return JsonUtility.ToJson(new Report { sprites=checkedSprites, characters=ids.Length, spriteLoadsPassed=true, uiLookupsPassed=true, combatRenderVerified=false });
    }
}
